extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var player := instantiate_script("res://story/story_player.gd") as Node
	if not check("player", player != null, "Lo script res://story/story_player.gd deve potersi istanziare"):
		return

	var test_data: Dictionary = {
		"version": 1,
		"story_file": "res://story/chapters/chapter_01.json",
		"line_index": 0,
		"variables": {},
		"background": "res://assets/sprites/background.png",
		"music": "res://assets/audio/music_loop.wav"
	}

	call_if_exists(player, "restore_from_save", [test_data])

	var bg_val = get_prop(player, "_current_background", "")
	var music_val = get_prop(player, "_current_music", "")

	check("bg_restored", String(bg_val) == "res://assets/sprites/background.png", "_current_background deve contenere lo sfondo passato nel salvataggio (trovato '%s')" % String(bg_val))
	check("music_restored", String(music_val) == "res://assets/audio/music_loop.wav", "_current_music deve contenere la musica passata nel salvataggio (trovato '%s')" % String(music_val))
